// Custom Worker entry: the OpenNext build only exports a fetch handler, and the game's
// daily cleanup used to be a Vercel cron. Cloudflare invokes `scheduled` instead, so we
// call the same /api/cron/cleanup route through the Worker's own service binding.
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type CronEnv = {
  CRON_SECRET?: string;
  WORKER_SELF_REFERENCE?: { fetch(input: Request): Promise<Response> };
};

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: CronEnv, ctx: { waitUntil(promise: Promise<unknown>): void }) {
    if (!env.CRON_SECRET || !env.WORKER_SELF_REFERENCE) return;
    const req = new Request("https://streetquest.remixt.app/api/cron/cleanup", {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      env.WORKER_SELF_REFERENCE.fetch(req).then((res) => {
        if (!res.ok) console.error(`[cron] cleanup failed: ${res.status}`);
      }),
    );
  },
};
